import shutil
import re
import openpyxl
from decimal import Decimal, ROUND_HALF_UP

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

if "Dashboard" not in wb.sheetnames:
    ws = wb.create_sheet("Dashboard")
else:
    ws = wb["Dashboard"]

def parse_number(value):
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = str(value).strip()
    if not s or s.startswith("="):
        return None
    m = re.search(r"-?\d+(?:\.\d+)?", s)
    if m:
        try:
            return float(m.group())
        except ValueError:
            return None
    return None

b5_raw = vals["Dashboard"]["B5"].value
b6_raw = vals["Dashboard"]["B6"].value

total = parse_number(b5_raw)
good = parse_number(b6_raw)

if total is None or good is None:
    trades_ws = vals["Trades"]
    total = 0
    good = 0
    for row in trades_ws.iter_rows(min_row=2, values_only=True):
        if len(row) < 14:
            continue
        position = row[2]
        stopped = row[13]
        if position in ("LONG", "SHORT"):
            total += 1
            if stopped == "NO":
                good += 1
    total = float(total)
    good = float(good)

if total == 0:
    pct = 0.0
else:
    pct = good / total

pct_int = (Decimal(str(pct)) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP)
answer = f"{pct_int}% WIN RATE"

ws["B8"] = answer
ws["B8"].number_format = "General"

wb.save(OUT)

print("B5:", b5_raw)
print("B6:", b6_raw)
print("total:", total)
print("good:", good)
print("B8:", answer)
